export const LINEAR_EQUATIONS_ACTIVITIES = [
{n:1,type:"mcq",micro:"Kecuraman konkret (tanjakan)",q:"Tanjakan A naik 1 meter untuk setiap 2 meter kamu berjalan maju. Tanjakan B naik 1 meter untuk setiap 5 meter kamu berjalan maju. Tanjakan mana yang lebih curam?",options:["Tanjakan A","Tanjakan B","Keduanya sama curamnya"],answer:0,explain:"Tanjakan A memperoleh tinggi lebih cepat relatif terhadap jarak maju (1 dalam 2, dibandingkan 1 dalam 5), jadi itu lebih curam.",hint:"Tanjakan mana yang memperoleh lebih banyak tinggi untuk jumlah jalan maju yang sama?"},
{n:2,type:"mcq",micro:"Laju tetap (kecepatan)",q:"Sebuah mobil berjalan dengan kecepatan tetap 60 km setiap jam. Jika berjalan selama 3 jam, seberapa jauh jaraknya?",options:["63 km","180 km","20 km"],answer:1,explain:"Dengan kecepatan tetap 60 km/jam selama 3 jam: 60 × 3 = 180 km.",hint:"Jika kecepatannya tetap sama setiap jam, kalikan kecepatan dengan jumlah jam."},
{n:3,type:"tf",micro:"Kecepatan tetap berarti jarak tetap per jam",q:"Benar atau Salah: Jika sebuah mobil berjalan dengan kecepatan tetap, jarak yang ditempuhnya setiap jam terus berubah-ubah.",answer:false,explain:"Kecepatan tetap berarti jarak yang sama ditempuh dalam setiap interval waktu yang sama.",hint:"Apakah 'kecepatan tetap' berarti mobil itu bertambah dan berkurang kecepatannya secara acak, atau berjalan dengan laju yang sama sepanjang waktu?"},
{n:4,type:"mcq",micro:"Biaya tetap plus laju (hubungan linear)",q:"Sebuah taksi mengenakan biaya awal tetap Rp3.000, plus Rp2.000 untuk setiap kilometer yang ditempuh. Berapa total biaya untuk perjalanan 4 km?",options:["Rp8.000","Rp9.000","Rp11.000"],answer:2,explain:"3.000 + 2.000×4 = 3.000 + 8.000 = 11.000.",hint:"Jumlahkan biaya tetap dengan laju dikalikan jumlah kilometernya."},
{n:5,type:"mcq",micro:"Membuat timbangan tidak seimbang (dasar untuk variabel di kedua sisi)",q:"Sebuah timbangan neraca memiliki 2 kantong tidak diketahui identik di kiri, dan 2 kantong tidak diketahui identik di kanan, tetapi berat ekstra 5kg lalu ditambahkan hanya ke sisi kanan. Apa yang terjadi?",options:["Miring ke bawah di sisi kanan, karena ekstra 5kg membuat sisi itu lebih berat","Miring ke bawah di sisi kiri, karena kantong di sisi kiri tampak lebih besar dan lebih berat","Tetap seimbang, karena kantong tidak diketahui itu identik sehingga ekstra 5kg tidak berpengaruh"],answer:0,explain:"Menambahkan berat ke hanya satu sisi merusak keseimbangan, membuat sisi itu miring ke bawah.",hint:"Jika kedua sisi mulai sama, apakah menambahkan berat ekstra ke hanya satu sisi menjaga mereka tetap sama?"},
{n:6,type:"mcq",micro:"Membandingkan dua laju tetap",q:"Tanaman A tumbuh 2 cm setiap minggu. Tanaman B tumbuh 3 cm setiap minggu. Setelah beberapa minggu, dengan asumsi mereka mulai dengan tinggi yang sama, tanaman mana yang akan lebih tinggi?",options:["Tanaman A","Tanaman B","Mereka akan selalu tetap sama tingginya"],answer:1,explain:"Tumbuh 3 cm/minggu menambah tinggi lebih cepat daripada tumbuh 2 cm/minggu, jadi Tanaman B akan unggul seiring waktu.",hint:"Tanaman mana yang mendapat lebih banyak tinggi untuk setiap minggu yang berlalu?"},
{n:7,type:"tf",micro:"Intuisi kecuraman",q:"Benar atau Salah: Bukit yang 'lebih curam' berarti kamu memperoleh lebih banyak tinggi untuk jarak maju yang sama, dibandingkan bukit yang 'lebih landai.'",answer:true,explain:"Kecuraman adalah tentang seberapa banyak tinggi yang kamu peroleh per satuan jarak maju — ini adalah akar sehari-hari dari kemiringan (slope).",hint:"Apakah bukit yang lebih curam membuatmu mendaki lebih tinggi untuk jumlah langkah maju yang sama, atau lebih sedikit?"},
{n:8,type:"mcq",micro:"Koordinat konkret (berjalan di kisi)",q:"Mulai dari sudut kisi blok kota, kamu berjalan 3 blok ke timur dan 2 blok ke utara. Bagaimana kamu akan menggambarkan posisi barumu menggunakan dua angka?",options:["Hanya satu angka yang dibutuhkan untuk menggambarkan posisi pada kisi","Posisimu tidak bisa digambarkan dengan angka","3 blok ke samping, 2 blok ke atas — seperti koordinat (3, 2)"],answer:2,explain:"Posisi pada kisi datar membutuhkan dua angka: seberapa jauh ke samping, dan seberapa jauh ke atas.",hint:"Akankah hanya mengatakan '3 blok' memberitahu seseorang tempat tepatmu, tanpa juga mengatakan seberapa jauh ke atas?"},
{n:9,type:"mcq",micro:"Mengapa pola biaya disebut 'linear'",q:"Sebuah paket telepon berbiaya tetap Rp10.000 per bulan plus Rp50 per pesan teks yang dikirim. Mengapa ini disebut pola biaya 'linear'?",options:["Karena total biaya bertambah dengan jumlah yang persis sama (Rp50) untuk setiap pesan teks tambahan, laju yang tetap dan konsisten","Karena total biaya berubah-ubah secara tidak teratur dari bulan ke bulan, tanpa laju tetap pada setiap pesan teks yang dikirim","Karena biaya tetap Rp10.000 bertambah setiap kali kamu mengirim pesan, sehingga laju biayanya selalu naik dengan jumlah yang makin besar"],answer:0,explain:"Laju perubahan yang tetap per satuan (setiap teks tambahan) persis apa yang membuat suatu hubungan linear.",hint:"Apakah setiap teks tambahan menambahkan jumlah yang sama ke tagihan, atau jumlah yang berbeda setiap kali?"},
{n:10,type:"mcq",micro:"Laju menurun konkret",q:"Sebuah lilin tingginya 20 cm dan terbakar habis 2 cm setiap jam. Apa yang terjadi pada tingginya seiring waktu?",options:["Bertambah stabil dengan jumlah yang sama setiap jam","Berkurang secara stabil dengan jumlah yang sama setiap jam","Tetap sama tingginya selama beberapa jam pertama lalu berubah"],answer:1,explain:"Kehilangan 2 cm tetap setiap jam adalah penurunan yang stabil dan konsisten — akar fisik dari kemiringan negatif.",hint:"Apakah lilin itu bertambah tinggi, berkurang, atau tetap sama seiring berlalunya waktu?"},
{n:11,type:"tf",micro:"Definisi hubungan linear",q:"Benar atau Salah: Dua jumlah memiliki hubungan 'linear' hanya jika kedua angkanya kecil.",answer:false,explain:"Hubungan linear ditandai oleh laju perubahan yang tetap per satuan — bukan oleh besar-kecilnya angka.",hint:"Apakah gagasan kunci 'linear' tentang laju yang tetap, atau tentang angka yang kecil?"},
{n:12,type:"mcq",micro:"Menyusun skenario perbandingan nyata",q:"Kamu punya Rp20.000 dan menabung Rp5.000 per minggu. Temanmu punya Rp8.000 dan menabung Rp7.000 per minggu. Pertanyaan alami apa yang ditimbulkan situasi ini?",options:["Setelah berapa minggu kalian akan sama-sama kehabisan tabungan?","Siapa di antara kalian yang lebih hemat dalam membelanjakan uang?","Setelah berapa minggu kalian berdua akan menabung total jumlah yang sama?"],answer:2,explain:"Membandingkan dua jumlah awal berbeda dan laju tetap berbeda secara alami mengarah pada pertanyaan kapan totalnya akan cocok — akar dunia nyata dari menyelesaikan sistem persamaan.",hint:"Karena kamu mulai dengan lebih banyak tetapi menabung lebih lambat, bisakah temanmu akhirnya mengejar?"},
{n:13,type:"mcq",micro:"Soal cerita laju tetap (pengurasan)",q:"Sebuah tangki air mulai dengan 100 liter dan terkuras 5 liter per menit. Setelah berapa menit tangki itu akan kosong?",options:["20 menit","5 menit","95 menit"],answer:0,explain:"100 ÷ 5 = 20 menit untuk semua air terkuras dengan laju tetap itu.",hint:"Bagi total jumlahnya dengan berapa banyak yang terkuras setiap menit."},
{n:14,type:"mcq",micro:"Membandingkan dua paket biaya-tetap-plus-laju",q:"Paket Gym A berbiaya Rp300.000 untuk bergabung plus Rp100.000/bulan. Paket Gym B berbiaya Rp0 untuk bergabung plus Rp150.000/bulan. Paket mana yang berbiaya lebih sedikit di bulan pertama?",options:["Paket A","Paket B","Biayanya persis sama di bulan 1"],answer:1,explain:"Bulan 1: Paket A = 300.000+100.000 = Rp400.000, Paket B = 0+150.000 = Rp150.000 — Paket B lebih murah pada awalnya.",hint:"Jumlahkan biaya pendaftaran dan laju bulan pertama setiap paket secara terpisah, lalu bandingkan."},
{n:15,type:"tf",micro:"Kecuraman tetap pada bukit nyata",q:"Benar atau Salah: Pada bukit nyata, jika kamu memperoleh tinggi yang persis sama untuk setiap meter yang kamu jalani maju sepanjang jalan naik, bukit itu memiliki kecuraman yang tetap dan tidak berubah.",answer:true,explain:"Kenaikan tinggi yang stabil per meter maju persis apa yang dimaksud kemiringan tetap secara fisik.",hint:"Apakah memperoleh tinggi yang SAMA untuk setiap meter berarti kecuraman bukit itu berubah atau tetap sama?"},
{n:16,type:"mcq",micro:"Petunjuk ketidakseimbangan konkret",q:"Pada Jungkat-jungkit A, kamu dan seorang teman dengan berat sama duduk di ujung berlawanan dan itu seimbang sempurna. Pada Jungkat-jungkit B, kamu duduk dengan ransel berat sementara temanmu yang sama duduk tanpa ransel, dan itu TIDAK seimbang. Apa yang diberitahukan ketidakseimbangan pada Jungkat-jungkit B ini padamu?",options:["Kedua sisi harus tetap sama beratnya terlepas dari ranselnya","Jungkat-jungkit B rusak dan tidak bisa dipercaya","Sisi dengan ransel sekarang lebih berat dari sisi lain"],answer:2,explain:"Menambahkan berat ekstra (ransel) ke satu sisi, sementara sisi lain tetap sama, membuat sisi itu lebih berat dan merusak keseimbangan.",hint:"Jika kamu mulai seimbang secara merata, apakah menambahkan ransel berat ke hanya satu sisi menjaga segalanya tetap sama?"},
{n:17,type:"mcq",micro:"Intuisi intersep konkret (titik awal)",q:"Sebuah rekening tabungan sudah punya Rp500.000 di dalamnya bahkan sebelum kamu mulai menambahkan tabungan mingguan Rp100.000-mu. Apa yang diwakili Rp500.000 awal itu?",options:["Jumlah awal, sebelum minggu-minggu menabung berlalu","Laju tabungan per minggu yang tetap Rp100.000","Jumlah seluruh uang setelah 52 minggu menabung"],answer:0,explain:"Rp500.000 itu adalah jumlah yang hadir pada 'minggu nol,' sebelum penambahan mingguan apa pun terjadi — akar dunia nyata dari intersep-y.",hint:"Apakah Rp500.000 itu sesuatu yang kamu tambahkan setiap minggu, atau sesuatu yang sudah ada di sana sejak awal?"},
{n:18,type:"mcq",micro:"Mengenali laju yang stabil",q:"Sebuah bus menempuh 40 km pada jam pertama, 40 km pada jam kedua, dan 40 km pada jam ketiga. Apa yang kamu perhatikan tentang kecepatannya?",options:["Ia melambat sedikit demi sedikit setiap jamnya","Ia berjalan dengan kecepatan yang stabil dan tetap setiap jam","Ia mempercepat lajunya sedikit demi sedikit tiap jam"],answer:1,explain:"Menempuh jarak yang sama di setiap jam yang sama adalah definisi kecepatan tetap.",hint:"Apakah jarak yang ditempuh setiap jam berubah, atau tetap sama?"},
{n:19,type:"mcq",micro:"Gagasan perpotongan konkret",q:"Dua teman mulai berjalan menuju satu sama lain dari ujung berlawanan jalan lurus pada waktu yang sama. Apa yang akhirnya akan terjadi?",options:["Mereka tidak akan pernah berada di tempat yang sama pada waktu yang sama","Mereka akan berakhir berjalan dalam lingkaran","Mereka akan bertemu di suatu titik di sepanjang jalan itu"],answer:2,explain:"Dua orang bergerak menuju satu sama lain di sepanjang jalur lurus yang sama akhirnya akan menempati tempat yang sama — akar dunia nyata dari dua garis bertemu di titik perpotongan.",hint:"Jika kedua orang terus berjalan menuju satu sama lain tanpa berhenti, haruskah mereka akhirnya bersilangan?"},
{n:20,type:"mcq",micro:"Memeriksa gagasan tentang hubungan linear",q:"Seseorang berkata 'hubungan antara dua jumlah hanya linear jika melibatkan uang.' Apakah ini benar?",options:["Salah — hubungan linear bisa melibatkan dua jumlah apa pun yang berubah dengan laju tetap relatif satu sama lain, seperti jarak dan waktu, atau tinggi dan nomor minggu","Benar — hubungan linear hanya terjadi bila kedua jumlah berhubungan dengan uang, sehingga jarak dan waktu atau tinggi dan minggu tidak pernah linear","Benar — hubungan linear hanya bisa dipakai pada situasi jual-beli, sedangkan fenomena fisik seperti gerak benda selalu berhubungan dengan cara yang berbeda"],answer:0,explain:"Linearitas adalah tentang laju perubahan tetap antara dua jumlah apa pun, bukan khusus tentang uang.",hint:"Bisakah perjalanan mobil berkecepatan tetap (jarak vs waktu) juga menjadi contoh hubungan linear, tanpa uang yang terlibat?"},
{n:21,type:"mcq",micro:"Membaca koordinat yang diplot",q:"Sebuah titik pada grafik diplot 3 satuan ke kanan dan 5 satuan ke atas dari titik asal. Bagaimana titik ini ditulis sebagai koordinat?",options:["(5, 3)","(3, 5)","(3, -5)"],answer:1,explain:"Menurut konvensi, koordinat ditulis (posisi horizontal, posisi vertikal): 3 kanan, 5 atas.",hint:"Angka mana yang ditulis dulu dalam pasangan koordinat — pergerakan ke samping, atau pergerakan atas/bawah?"},
{n:22,type:"mcq",micro:"Membandingkan kecuraman pada grafik",q:"Garis A pada grafik naik tajam dari kiri ke kanan, sementara Garis B naik sangat landai. Garis mana yang kemiringannya lebih besar?",options:["Garis B","Kedua garis memiliki kemiringan yang sama","Garis A"],answer:2,explain:"Garis yang naik lebih tajam memiliki kemiringan yang lebih besar (laju perubahan lebih curam) daripada garis yang naik landai.",hint:"Garis mana yang naik lebih tinggi untuk jumlah pergerakan menyamping yang sama?"},
{n:23,type:"mcq",micro:"Membaca pola dalam tabel",q:"Sebuah tabel menunjukkan: x=1, y=3; x=2, y=5; x=3, y=7. Pola apa yang kamu perhatikan dalam bagaimana y berubah saat x bertambah 1?",options:["y bertambah 2 setiap kali x bertambah 1","y bertambah 1 setiap kali x bertambah 1","y tetap persis sama"],answer:0,explain:"Setiap langkah +1 dalam x sesuai dengan langkah +2 dalam y: 3→5→7.",hint:"Lihat selisih antara setiap nilai y yang berturut-turut."},
{n:24,type:"mcq",micro:"Membaca intersep-y dari grafik",q:"Sebuah garis grafik memotong sumbu vertikal (y) di titik (0, 4). Apa nama titik ini?",options:["Intersep-x","Intersep-y","Kemiringan"],answer:1,explain:"Titik di mana garis memotong sumbu-y (di mana x=0) disebut intersep-y.",hint:"Sumbu mana yang menjadi tempat titik perpotongan ini berada — yang vertikal, atau yang horizontal?"},
{n:25,type:"order",micro:"Mengurutkan cara memplot titik",q:"Urutkan langkah-langkah berikut untuk memplot titik (2, 3) pada sebuah grafik.",items:["Dari titik asal, bergerak 2 satuan ke kanan","Mulai di titik asal (0,0)","Dari situ, bergerak 3 satuan ke atas, lalu tandai titiknya"],answer:[1,0,2],explain:"Mulai di titik asal, bergerak ke kanan sesuai nilai-x, lalu bergerak ke atas sesuai nilai-y.",hint:"Bisakah kamu bergerak 2 satuan ke kanan sebelum kamu bahkan mulai dari titik asal?"},
{n:26,type:"mcq",micro:"Membaca intersep-x dari grafik",q:"Sebuah garis grafik memotong sumbu horizontal (x) di titik (6, 0). Apa nama titik ini?",options:["Intersep-y","Titik asal","Intersep-x"],answer:2,explain:"Titik di mana garis memotong sumbu-x (di mana y=0) disebut intersep-x.",hint:"Sumbu mana yang menjadi tempat titik perpotongan khusus ini berada?"},
{n:27,type:"mcq",micro:"Membandingkan dua garis grafik (intuisi sejajar)",q:"Dua garis grafik naik dengan kecuraman yang persis sama tetapi memotong sumbu-y pada tinggi yang berbeda. Apa yang bisa kamu katakan tentang kedua garis ini?",options:["Mereka tidak akan pernah bertemu — mereka tetap berjarak sama selamanya","Mereka akan bertemu di titik tertentu, karena kecuraman yang sama berarti mereka saling mendekati","Mereka akan bertemu di sumbu-y, karena semua garis lurus pada akhirnya memotong sumbu itu bersama"],answer:0,explain:"Garis dengan kemiringan sama tetapi intersep-y berbeda adalah sejajar dan tidak pernah berpotongan.",hint:"Jika dua garis naik dengan laju yang persis sama tetapi mulai pada ketinggian berbeda, apakah celah di antara keduanya pernah menutup?"},
{n:28,type:"tf",micro:"Kemiringan negatif pada grafik",q:"Benar atau Salah: Pada grafik, garis yang menurun dari kiri ke kanan mewakili kemiringan positif.",answer:false,explain:"Garis yang menurun (saat x bertambah, y berkurang) justru memiliki kemiringan negatif.",hint:"Apakah garis yang jatuh saat kamu bergerak ke kanan berarti y bertambah atau berkurang?"},
{n:29,type:"mcq",micro:"Membaca diagram timbangan (variabel di kedua sisi)",q:"Sebuah diagram menunjukkan timbangan: 3 kotak 'x' identik di kiri, seimbang dengan 1 kotak 'x' plus berat 12kg di kanan. Persamaan apa yang diwakili diagram ini?",options:["3x = 12","3x = x + 12","x = 3 + 12"],answer:1,explain:"Panci kiri menunjukkan 3 kotak-x; panci kanan menunjukkan 1 kotak-x plus 12kg — keduanya seimbang.",hint:"Berapa banyak kotak 'x' yang ditunjukkan di setiap sisi gambar?"},
{n:30,type:"classify",micro:"Kemiringan positif, negatif, atau nol?",q:"Kelompokkan setiap deskripsi sebagai 'Kemiringan positif', 'Kemiringan negatif', atau 'Kemiringan nol (datar)'.",items:["Garis yang naik dari kiri ke kanan","Garis yang turun dari kiri ke kanan","Garis horizontal yang benar-benar datar","Garis yang naik curam ke atas"],groups:["Kemiringan positif","Kemiringan negatif","Kemiringan nol"],answer:{"Kemiringan positif":["Garis yang naik dari kiri ke kanan","Garis yang naik curam ke atas"],"Kemiringan negatif":["Garis yang turun dari kiri ke kanan"],"Kemiringan nol":["Garis horizontal yang benar-benar datar"]},explain:"Garis yang naik memiliki kemiringan positif, garis yang turun memiliki kemiringan negatif, dan garis datar memiliki kemiringan nol.",hint:"Apakah garis itu naik, turun, atau tetap rata saat kamu bergerak dari kiri ke kanan?"},
{n:31,type:"mcq",micro:"Membaca titik perpotongan (intuisi sistem)",q:"Dua garis digambar pada kisi yang sama, dan mereka berpotongan di titik (2, 5). Apa yang diwakili titik perpotongan ini?",options:["Satu nilai x saja di mana hanya persamaan pertama yang benar, sedangkan persamaan kedua salah","Pasangan angka yang tidak punya arti khusus, karena perpotongan garis hanya kebetulan dalam gambar","Satu nilai (x, y) di mana kedua persamaan garis itu benar pada saat yang sama"],answer:2,explain:"Titik perpotongan adalah penyelesaian bersama yang memenuhi kedua persamaan garis secara bersamaan.",hint:"Apakah titik perpotongan itu milik hanya satu garis, atau milik keduanya sekaligus?"},
{n:32,type:"mcq",micro:"Menafsirkan grafik perbandingan biaya nyata",q:"Sebuah grafik menunjukkan garis biaya Paket A naik lebih curam daripada Paket B, tetapi Paket A mulai lebih rendah pada sumbu-y. Apa mungkin arti ini?",options:["Paket A mulai lebih murah tetapi biayanya meningkat lebih cepat, jadi bisa menjadi lebih mahal daripada Paket B seiring waktu","Paket A selalu lebih murah daripada Paket B, karena titik awalnya lebih rendah sehingga biayanya tidak akan pernah melampaui Paket B","Paket A selalu lebih mahal daripada Paket B, karena garisnya lebih curam sejak awal, walaupun titik awalnya lebih rendah di sumbu-y"],answer:0,explain:"Titik awal yang lebih rendah tetapi kemiringan yang lebih curam berarti sebuah paket bisa mulai murah dan kemudian melampaui paket lain dalam biaya.",hint:"Jika satu garis mulai lebih rendah tetapi naik lebih cepat, bisakah ia akhirnya melewati garis lainnya?"},
{n:33,type:"mcq",micro:"Menggambarkan distribusi (kantong berkelompok)",q:"Sebuah gambar menunjukkan 3 kantong identik, masing-masing berisi kotak 'x' plus 2 barang ekstra. Berapa total barang, ditulis sebagai ekspresi terdistribusi?",options:["3x + 2","3x + 6","x + 6"],answer:1,explain:"Setiap dari 3 kantong menyumbang baik x maupun 2 barang ekstra, jadi kedua bagian dikalikan dengan 3.",hint:"Apakah setiap kantong berisi BAIK x MAUPUN 2 barang itu, berarti keduanya perlu dikalikan dengan 3?"},
{n:34,type:"mcq",micro:"Membaca tabel untuk laju negatif",q:"Sebuah tabel menunjukkan: x=0, y=10; x=1, y=8; x=2, y=6. Apa yang terjadi pada y saat x bertambah?",options:["y bertambah 2 setiap kali x bertambah 1","y tetap persis sama","y berkurang 2 setiap kali x bertambah 1"],answer:2,explain:"Setiap langkah +1 dalam x sesuai dengan langkah −2 dalam y: 10→8→6.",hint:"Apakah nilai-y bertambah besar atau berkurang saat x naik?"},
{n:35,type:"tf",micro:"Kemiringan sebagai kecuraman",q:"Benar atau Salah: Kecuraman garis grafik (seberapa tajam ia naik atau turun) adalah apa yang kita sebut kemiringannya.",answer:true,explain:"Kemiringan persis adalah ukuran matematis dari kecuraman garis.",hint:"Apakah 'kemiringan' hanya kata lain untuk seberapa curam garis itu terlihat?"},
{n:36,type:"mcq",micro:"Melanjutkan diagram timbangan",q:"Menggunakan gambar yang sama (3x = x + 12), jika kamu menghapus 1 kotak 'x' dari KEDUA sisi, apa yang ditunjukkan timbangan selanjutnya?",options:["2x = 12","2x = 11","3x = 12"],answer:0,explain:"Menghapus 1 kotak-x dari '3x' dan 'x + 12' menyisakan 2x = 12.",hint:"Kurangkan satu kotak-x dari setiap sisi — apa yang tersisa di setiap panci?"},
{n:37,type:"mcq",micro:"Membaca titik perpotongan grafik perbandingan biaya nyata",q:"Sebuah grafik menunjukkan dua garis biaya paket telepon berpotongan di 'x = 200 menit.' Apa yang diberitahukan titik perpotongan ini kepada pelanggan?",options:["Kedua paket berbiaya Rp200.000 apa pun yang terjadi","Pada tepat 200 menit penggunaan, kedua paket berbiaya jumlah yang sama","Grafik itu menunjukkan kesalahan karena garis tidak seharusnya berpotongan"],answer:1,explain:"Titik perpotongan dua garis biaya menunjukkan tingkat penggunaan yang tepat di mana kedua paket memiliki biaya yang sama.",hint:"Apa artinya dua garis biaya yang BERBEDA berada pada ketinggian yang persis sama pada satu nilai-x tertentu?"},
{n:38,type:"mcq",micro:"Menjembatani piktorial ke abstrak (sistem)",q:"Melihat beberapa contoh di mana dua garis grafik berpotongan di tepat satu titik, pola apa yang kamu perhatikan tentang titik perpotongan itu?",options:["Titik perpotongan itu hanya membuat persamaan pertama benar, sedangkan persamaan kedua selalu salah di titik yang sama","Titik perpotongan itu berubah-ubah tergantung gambar, sehingga tidak mewakili pasangan angka yang tetap pada kedua persamaan","Satu titik itu adalah pasangan (x, y) tunggal yang membuat KEDUA persamaan garis benar pada saat yang sama"],answer:2,explain:"Setiap titik perpotongan, terlepas dari garis spesifiknya, mewakili penyelesaian bersama yang memenuhi kedua persamaan.",hint:"Apakah titik perpotongan setiap contoh melayani peran dasar yang sama, meskipun garisnya sendiri berbeda?"},
{n:39,type:"mcq",micro:"Membaca biaya awal dari grafik",q:"Sebuah grafik menunjukkan biaya perjalanan taksi: pada x=0 km garisnya mulai di y=Rp3.000, dan setelah x=5 km ia berada di y=Rp13.000. Berapa biaya awal tetap yang ditunjukkan pada grafik?",options:["Rp3.000","Rp13.000","Rp10.000"],answer:0,explain:"Nilai y ketika x=0 (intersep-y) mewakili biaya awal tetap sebelum jarak apa pun ditempuh.",hint:"Berapa biaya yang ditunjukkan pada grafik sebelum kilometer apa pun ditempuh (pada x=0)?"},
{n:40,type:"mcq",micro:"Memilih strategi berbasis gambar untuk perpotongan",q:"Untuk menemukan di mana dua garis grafik berpotongan tanpa mengukur secara tepat, apa pendekatan yang membantu?",options:["Ukur panjang kedua garis dengan penggaris lalu bandingkan panjangnya, karena garis yang lebih panjang pasti berpotongan lebih awal","Temukan di mana kedua garis yang diplot secara visual berpotongan, lalu baca koordinat (x, y) pada titik tepat itu","Tebak titik perpotongan dari satu garis saja tanpa melihat garis lainnya, karena garis kedua akan menyesuaikan dengan sendirinya"],answer:1,explain:"Titik perpotongan ditemukan dengan menemukan lokasi di mana kedua garis secara fisik bertemu pada kisi.",hint:"Apakah menemukan perpotongan membutuhkan melihat kedua garis bersama, atau hanya satu di antaranya?"},
{n:41,type:"mcq",micro:"Menyelesaikan dengan variabel di kedua sisi",q:"Selesaikan: 3x = x + 12.",options:["x = 12","x = 4","x = 6"],answer:2,explain:"Kurangkan x dari kedua sisi: 2x = 12, lalu bagi dengan 2: x = 6.",hint:"Kurangkan suku-x yang lebih kecil dari kedua sisi dulu, untuk mengumpulkan semua x di satu sisi."},
{n:42,type:"mcq",micro:"Menyelesaikan dengan variabel di kedua sisi",q:"Selesaikan: 5x + 2 = 2x + 11.",options:["x = 3","x = 13","x = 4,33"],answer:0,explain:"Kurangkan 2x dari kedua sisi (3x + 2 = 11), lalu kurangkan 2 (3x = 9), lalu bagi dengan 3: x = 3.",hint:"Pertama kumpulkan suku-x di satu sisi, lalu angka konstanta di sisi lain."},
{n:43,type:"mcq",micro:"Menyelesaikan dengan tanda kurung",q:"Selesaikan: 2(x + 3) = 14.",options:["x = 7","x = 4","x = 5,5"],answer:1,explain:"Distribusikan: 2x + 6 = 14, kurangkan 6: 2x = 8, bagi dengan 2: x = 4.",hint:"Distribusikan 2 ke dalam tanda kurung dulu, sebelum melakukan hal lain."},
{n:44,type:"mcq",micro:"Menyelesaikan dengan pecahan",q:"Selesaikan: x/2 + 3 = 7.",options:["x = 2","x = 20","x = 8"],answer:2,explain:"Kurangkan 3 dari kedua sisi: x/2 = 4, lalu kalikan kedua sisi dengan 2: x = 8.",hint:"Isolasi dulu suku pecahannya dengan mengurangkan 3, lalu batalkan pembagian oleh 2."},
{n:45,type:"mcq",micro:"Menghitung kemiringan dari dua titik",q:"Temukan kemiringan garis yang melalui titik (1, 2) dan (3, 8).",options:["3","6","2"],answer:0,explain:"Kemiringan = (8−2)/(3−1) = 6/2 = 3.",hint:"Kemiringan adalah perubahan y dibagi perubahan x antara kedua titik."},
{n:46,type:"mcq",micro:"Menghitung kemiringan dari dua titik (negatif)",q:"Temukan kemiringan garis yang melalui titik (0, 5) dan (2, 1).",options:["2","-2","-4"],answer:1,explain:"Kemiringan = (1−5)/(2−0) = −4/2 = −2.",hint:"Kurangkan nilai-y dan nilai-x dalam urutan yang sama, lalu bagi."},
{n:47,type:"mcq",micro:"Mengidentifikasi kemiringan dan intersep-y",q:"Dalam persamaan y = 3x + 7, apa kemiringan dan intersep-y-nya?",options:["kemiringan = 7, intersep-y = 3","kemiringan = 3, intersep-y = 0","kemiringan = 3, intersep-y = 7"],answer:2,explain:"Dalam bentuk y = mx + b, m adalah kemiringan dan b adalah intersep-y: di sini m=3, b=7.",hint:"Dalam y = mx + b, posisi huruf mana yang memegang kemiringan, dan mana yang memegang intersep-y?"},
{n:48,type:"order",micro:"Mengurutkan penyelesaian variabel-di-kedua-sisi",q:"Urutkan langkah-langkah berikut untuk menyelesaikan persamaan 4x - 3 = 2x + 9.",items:["Bagi kedua sisi dengan 2 untuk mendapat x = 6","Kurangkan 2x dari kedua sisi untuk mendapat 2x - 3 = 9","Jumlahkan 3 ke kedua sisi untuk mendapat 2x = 12","Mulai dengan persamaan asli 4x - 3 = 2x + 9"],answer:[3,1,2,0],explain:"Mulai dengan persamaannya, kumpulkan suku-x di satu sisi, kumpulkan konstanta, lalu bagi.",hint:"Bisakah kamu menjumlahkan 3 ke kedua sisi sebelum kamu pertama mengumpulkan suku-x di satu sisi?"},
{n:49,type:"mcq",micro:"Menemukan intersep-x secara aljabar",q:"Temukan intersep-x garis y = 2x - 8 (di mana y = 0).",options:["x = 4","x = -8","x = 8"],answer:0,explain:"Tetapkan y=0: 0 = 2x − 8, jadi 2x = 8, memberikan x = 4.",hint:"Ganti y=0 ke dalam persamaan, lalu selesaikan untuk x."},
{n:50,type:"mcq",micro:"Menemukan intersep-y secara aljabar",q:"Temukan intersep-y garis y = 2x - 8 (di mana x = 0).",options:["y = 8","y = -8","y = 2"],answer:1,explain:"Mengganti x=0: y = 2(0) − 8 = −8.",hint:"Ganti x=0 ke dalam persamaan dan sederhanakan."},
{n:51,type:"mcq",micro:"Menulis bentuk kemiringan-intersep",q:"Sebuah garis memiliki kemiringan 4 dan intersep-y -1. Apa persamaannya dalam bentuk y = mx + b?",options:["y = -1x + 4","y = 4x + 1","y = 4x - 1"],answer:2,explain:"Mengganti m=4 dan b=−1 ke dalam y = mx + b memberikan y = 4x − 1.",hint:"Dalam y = mx + b, apakah m atau b yang mewakili kemiringan, dan nilai mana yang masuk ke sana?"},
{n:52,type:"mcq",micro:"Menyelesaikan dengan tanda kurung dan pengurangan",q:"Selesaikan: 3(x - 2) = 9.",options:["x = 5","x = 3","x = 1"],answer:0,explain:"Distribusikan: 3x − 6 = 9, jumlahkan 6: 3x = 15, bagi dengan 3: x = 5.",hint:"Distribusikan 3 dulu, ingat itu mengalikan kedua suku di dalam tanda kurung."},
{n:53,type:"mcq",micro:"Menyelesaikan dengan variabel di kedua sisi",q:"Selesaikan: 7x - 4 = 3x + 16.",options:["x = 3","x = 5","x = 20"],answer:1,explain:"Kurangkan 3x dari kedua sisi (4x − 4 = 16), jumlahkan 4 (4x = 20), bagi dengan 4: x = 5.",hint:"Kumpulkan suku-x di satu sisi dulu, lalu konstanta di sisi lain."},
{n:54,type:"mcq",micro:"Menyelesaikan sistem sederhana dengan substitusi",q:"Selesaikan sistem: y = x + 2 dan y = 3x - 4.",options:["x = 1, y = 3","x = 5, y = 3","x = 3, y = 5"],answer:2,explain:"Tetapkan kedua ekspresi untuk y sama: x+2 = 3x−4, jadi 6 = 2x, memberikan x=3, dan y = 3+2 = 5.",hint:"Karena kedua persamaan sama dengan y, tetapkan sisi kanannya sama satu sama lain."},
{n:55,type:"mcq",micro:"Menyelesaikan sistem sederhana dengan substitusi",q:"Selesaikan sistem: y = 2x dan y = x + 6.",options:["x = 6, y = 12","x = 3, y = 6","x = 6, y = 6"],answer:0,explain:"Tetapkan 2x = x+6, jadi x=6, dan y = 2(6) = 12.",hint:"Tetapkan kedua ekspresi untuk y sama satu sama lain, lalu selesaikan untuk x."},
{n:56,type:"classify",micro:"Satu, tidak ada, atau tak terhingga banyak penyelesaian?",q:"Kelompokkan setiap persamaan sebagai 'Memiliki satu penyelesaian', 'Tidak memiliki penyelesaian', atau 'Memiliki tak terhingga banyak penyelesaian'.",items:["2x + 1 = 2x + 5","3x = 12","4x + 2 = 4x + 2","x - 1 = 9"],groups:["Memiliki satu penyelesaian","Tidak memiliki penyelesaian","Memiliki tak terhingga banyak penyelesaian"],answer:{"Memiliki satu penyelesaian":["3x = 12","x - 1 = 9"],"Tidak memiliki penyelesaian":["2x + 1 = 2x + 5"],"Memiliki tak terhingga banyak penyelesaian":["4x + 2 = 4x + 2"]},explain:"Jika suku-x saling meniadakan dan menyisakan pernyataan salah, tidak ada penyelesaian; jika saling meniadakan dan menyisakan pernyataan benar, ada tak terhingga banyak; jika tidak, ada tepat satu penyelesaian.",hint:"Coba kurangkan suku-x yang cocok dari kedua sisi setiap persamaan — apa yang tersisa?"},
{n:57,type:"mcq",micro:"Memeriksa apakah suatu titik terletak pada garis",q:"Apakah titik (2, 7) terletak pada garis y = 3x + 1?",options:["Tidak, karena 3(2) + 1 tidak sama dengan 7","Ya, karena 3(2) + 1 = 7, yang cocok","Mustahil memeriksa tanpa grafik"],answer:1,explain:"Mengganti x=2 ke dalam persamaan memberikan y=7, cocok dengan nilai-y titik itu.",hint:"Ganti nilai-x titik itu ke dalam persamaan dan lihat apakah kamu mendapat nilai-y titik itu."},
{n:58,type:"mcq",micro:"Menyelesaikan persamaan dengan koefisien pecahan",q:"Selesaikan: 2x/3 = 8.",options:["x = 4","x = 16","x = 12"],answer:2,explain:"Kalikan kedua sisi dengan 3: 2x = 24, lalu bagi dengan 2: x = 12.",hint:"Kalikan kedua sisi dengan 3 dulu untuk membersihkan penyebutnya."},
{n:59,type:"mcq",micro:"Kemiringan garis horizontal",q:"Berapa kemiringan garis yang benar-benar horizontal (datar)?",options:["0","1","Tidak terdefinisi"],answer:0,explain:"Garis horizontal tidak memiliki kenaikan (tidak ada perubahan y), jadi kemiringannya 0.",hint:"Apakah garis datar naik atau turun sama sekali saat kamu bergerak di sepanjangnya?"},
{n:60,type:"mcq",micro:"Memilih langkah pertama",q:"Untuk menyelesaikan 6x + 4 = 2x + 20, apa yang harus kamu lakukan DULU?",options:["Bagi kedua sisi dengan 6 dulu","Kurangkan 2x dari kedua sisi","Kurangkan 20 dari kedua sisi"],answer:1,explain:"Mengumpulkan suku-x di satu sisi dulu (dengan mengurangkan 2x) adalah langkah pertama standar untuk persamaan variabel-di-kedua-sisi.",hint:"Suku mana yang 'menghalangi' di sisi tempat kamu akhirnya ingin hanya angka?"},
{n:61,type:"mcq",micro:"Mengapa kemiringan penting",q:"Mengapa kemiringan garis biaya-vs-penggunaan bermakna bagi pelanggan yang membandingkan paket telepon?",options:["Karena kemiringan hanya menunjukkan warna garis pada grafik biaya, sehingga tidak berpengaruh pada perbandingan paket telepon yang dilakukan pelanggan ketika memilih paket di toko","Karena kemiringan menunjukkan berapa biaya tetap yang harus dibayar setiap bulan walaupun pelanggan tidak memakai paket telepon sama sekali sepanjang bulan itu berlangsung","Karena kemiringan memberitahumu berapa banyak biaya meningkat untuk setiap unit tambahan yang digunakan (seperti setiap menit atau teks ekstra), yang penting untuk memprediksi biaya pada penggunaan tinggi"],answer:2,explain:"Kemiringan secara langsung mewakili laju sebenarnya di mana biaya tumbuh dengan penggunaan, alat perbandingan yang benar-benar berguna.",hint:"Akankah mengetahui seberapa cepat biaya suatu paket tumbuh per menit ekstra membantumu memprediksi tagihanmu pada penggunaan tinggi?"},
{n:62,type:"open",micro:"Analisis kesalahan",q:"Seorang siswa menyelesaikan 5x + 3 = 2x + 12 dengan menulis 5x + 2x = 12 + 3, mendapat 7x = 15. Temukan kesalahannya.",explain:"Membingungkan 'pindahkan suku ke sisi lain' dengan 'gabungkan di sisi yang sama' adalah kesalahan variabel-di-kedua-sisi yang umum.",hint:"Ketika sebuah suku menyeberang ke sisi lain tanda sama dengan, haruskah tandanya berubah?",sample:"Mereka memindahkan 2x ke sisi yang sama dengan 5x alih-alih menguranginya dari kedua sisi (yang seharusnya menyisakan 3x, bukan 7x), dan secara terpisah memindahkan 3 tanpa mengubah tandanya. Pendekatan yang benar: kurangkan 2x dari kedua sisi (3x + 3 = 12), lalu kurangkan 3 dari kedua sisi (3x = 9), memberikan x = 3."},
{n:63,type:"open",micro:"Memeriksa sebuah penyelesaian",q:"Setelah menyelesaikan 4x - 1 = 2x + 9 dan mendapat x = 5, bagaimana kamu akan memeriksa ini benar?",explain:"Mengganti ke kedua sisi persamaan ASLI adalah cara andal untuk memverifikasi penyelesaian variabel-di-kedua-sisi.",hint:"Akankah memasukkan x=5 ke sisi kiri DAN kanan persamaan asli mengonfirmasi bahwa keduanya sama?",sample:"Ganti x=5 ke dalam KEDUA sisi persamaan asli: sisi kiri 4(5)−1=19, sisi kanan 2(5)+9=19 — kedua sisi cocok, mengonfirmasi x=5 benar."},
{n:64,type:"mcq",micro:"Penalaran tentang persamaan tanpa penyelesaian",q:"Kamu menyelesaikan sebuah persamaan dan menyederhanakannya menjadi '5 = 9'. Apa arti ini?",options:["Persamaan itu tidak memiliki penyelesaian — tidak ada nilai x yang bisa pernah membuat kedua sisi itu sama","Persamaan itu memiliki satu penyelesaian, yaitu x = 5, karena angka di sisi kiri adalah nilai yang dicari","Persamaan itu memiliki tak terhingga banyak penyelesaian, karena kedua sisi bisa dibuat sama dengan memilih x apa saja"],answer:0,explain:"Pernyataan angka-tetap yang salah seperti 5=9 berarti persamaan aslinya adalah kontradiksi tanpa penyelesaian.",hint:"Bisakah dua angka tetap berbeda, seperti 5 dan 9, pernah benar-benar sama, tidak peduli berapa x-nya?"},
{n:65,type:"open",micro:"Penalaran dunia nyata",q:"Mengapa sebuah bisnis mungkin menggunakan persamaan linear seperti 'keuntungan = 15.000x - 2.000.000' (di mana x adalah unit terjual) alih-alih menghitung ulang keuntungan dari awal untuk setiap kemungkinan angka penjualan?",explain:"Satu rumus yang berlaku umum di semua kemungkinan angka penjualan jauh lebih efisien daripada perhitungan manual berulang.",hint:"Bisakah sebuah bisnis dengan cepat menemukan titik impasnya dengan menetapkan rumus keuntungan ke nol dan menyelesaikannya, alih-alih menebak?",sample:"Sebuah persamaan linear langsung menghitung keuntungan untuk BERAPA PUN unit yang terjual tanpa mengulang seluruh perhitungan setiap kali, dan juga mengungkapkan titik impas (di mana keuntungan=0) dengan satu perhitungan alih-alih coba-coba."},
{n:66,type:"mcq",micro:"Memilih strategi yang efisien untuk sistem",q:"Untuk menyelesaikan 50 sistem persamaan linear dua-variabel yang berbeda, mengapa substitusi (atau eliminasi) lebih efisien daripada menebak nilai sampai kebetulan berhasil?",options:["Karena menebak pasangan (x, y) lebih cepat dan selalu menemukan jawaban yang tepat, sedangkan substitusi dan eliminasi rumit sehingga lebih lama diselesaikan dalam jumlah besar","Karena substitusi/eliminasi secara andal menemukan titik perpotongan yang tepat melalui metode yang bisa diulang, sementara menebak bisa memakan waktu sangat lama atau melewatkan jawaban tepat sama sekali","Karena substitusi dan eliminasi hanya bekerja untuk satu sistem saja, sehingga untuk 50 sistem berbeda tiap sistem butuh metode baru yang harus ditemukan lebih dulu oleh siswa"],answer:1,explain:"Metode sistematis berskala andal di berbagai soal, tidak seperti menebak coba-coba.",hint:"Akankah menebak secara acak menjadi cara yang andal untuk menyelesaikan 50 sistem BERBEDA dengan cepat dan akurat?"},
{n:67,type:"open",micro:"Menyelidiki perbedaan hasil",q:"Dua siswa menyelesaikan sistem y=x+3 dan y=2x-1, dan mendapat (4,7) dan (2,5). Jelaskan rencana untuk menemukan jawaban yang benar.",explain:"Memeriksa setiap kandidat terhadap KEDUA persamaan asli secara andal mengungkapkan mana yang benar-benar benar.",hint:"Akankah mengganti setiap pasangan kandidat ke KEDUA persamaan (bukan hanya satu) mengungkapkan mana yang sebenarnya benar?",sample:"Ganti setiap pasangan kandidat ke KEDUA persamaan asli: (4,7): 7=4+3 ✓ dan 7=2(4)−1=7 ✓ (cocok keduanya!); (2,5): 5=2+3 ✓ tetapi 5=2(2)−1=3 ✗ (gagal persamaan kedua) — jadi (4,7) adalah titik perpotongan yang benar."},
{n:68,type:"mcq",micro:"Penalaran tentang tanda kemiringan",q:"Mengapa kemiringan negatif menunjukkan garis yang menurun dari kiri ke kanan?",options:["Karena kemiringan negatif berarti y bertambah saat x bertambah, yang secara visual muncul sebagai garis naik saat kamu bergerak ke kanan","Karena kemiringan negatif hanya berarti garis tersebut ada di bawah sumbu-x, tidak berkaitan dengan arah naik atau turunnya garis","Karena kemiringan negatif berarti y berkurang saat x bertambah, yang secara visual muncul sebagai garis jatuh saat kamu bergerak ke kanan"],answer:2,explain:"Tanda kemiringan langsung mencerminkan apakah y bertambah atau berkurang saat x bertambah.",hint:"Jika y menjadi lebih kecil setiap kali x menjadi lebih besar, akankah garis itu secara visual naik atau turun saat kamu bergerak ke kanan?"},
{n:69,type:"open",micro:"Penalaran tentang membandingkan dua paket",q:"Dua paket telepon berpotongan pada 200 menit pada grafik biaya. Mengapa mengetahui titik perpotongan tepat ini membantu pelanggan memutuskan paket mana yang dipilih?",explain:"Titik perpotongan menandai ambang penggunaan tepat di mana opsi yang lebih murah berganti, langsung berguna untuk keputusan nyata.",hint:"Akankah pelanggan yang menggunakan kurang dari 200 menit menginginkan paket berbeda daripada yang menggunakan lebih banyak?",sample:"Di bawah 200 menit, paket mana pun yang mulai lebih rendah/lebih datar akan lebih murah, dan di atas 200 menit paket lainnya menjadi lebih murah — mengetahui titik perpotongan tepat membiarkan pelanggan memilih paket yang cocok dengan penggunaan khas mereka alih-alih menebak."},
{n:70,type:"mcq",micro:"Penalaran tentang mendistribusikan tanda negatif",q:"Mengapa mendistribusikan -2(x - 5) memberikan -2x + 10, bukan -2x - 10?",options:["Karena -2 mengalikan KEDUA suku di dalam tanda kurung, dan -2 dikali -5 memberikan positif 10 (negatif kali negatif adalah positif)","Karena -2 hanya mengalikan suku pertama di dalam tanda kurung, jadi -2 dikali x memberikan -2x, sedangkan suku kedua tidak diubah menjadi 10","Karena -2 dikali -5 memberikan negatif 10 (negatif kali negatif adalah negatif), sehingga hasil akhirnya sama dengan -2x - 10"],answer:0,explain:"Mengalikan negatif dengan negatif memberikan positif — aturan tanda ini penting saat mendistribusikan.",hint:"Apa tanda hasilnya ketika kamu mengalikan angka negatif dengan angka negatif lainnya?"},
{n:71,type:"open",micro:"Estimasi sebagai penangkap kesalahan",q:"Sebelum menyelesaikan 6x + 4 = 2x + 40 secara tepat, bagaimana perkiraan cepat bisa membantumu menangkap kesalahan?",explain:"Perkiraan kasar bertindak sebagai pemeriksaan kewajaran yang bisa menandakan perhitungan tepat yang sangat salah.",hint:"Akankah kesenjangan besar antara perkiraan kasar dan jawaban tepat patut diselidiki?",sample:"Kira-kira, 4x dekat dengan 36 (40−4), jadi x kira-kira 9; jika perhitungan tepatmu memberikan x=90, ketidakcocokan besar itu akan menjadi sinyal jelas bahwa ada yang salah dalam langkahmu."},
{n:72,type:"mcq",micro:"Mengenali pola di berbagai sistem",q:"Melihat beberapa sistem di mana satu persamaan adalah y=x+a dan yang lain y=2x+b, apa yang kamu perhatikan tentang menemukan setiap titik perpotongan?",options:["Setiap sistem membutuhkan strategi yang berbeda tergantung nilai a dan b, sehingga tidak ada pola yang bisa dipakai untuk menyelesaikan sistem lain","Setiap sistem, terlepas dari nilai a dan b spesifiknya, diselesaikan dengan strategi substitusi yang sama (tetapkan kedua sisi kanan sama satu sama lain)","Setiap sistem diselesaikan dengan menjumlahkan kedua persamaan lebih dulu, tanpa peduli nilai a dan b, karena hasilnya selalu sama dengan nol"],answer:1,explain:"Strategi substitusi dasarnya berlaku umum di setiap sistem dengan bentuk yang sama ini.",hint:"Apakah setiap contoh sistem diselesaikan dengan cara yang persis sama, hanya dengan angka berbeda yang dimasukkan?"},
{n:73,type:"open",micro:"Refleksi pilihan strategi",q:"Jelaskan situasi terkait-kemiringan nyata di mana perkiraan visual cepat dari grafik sudah cukup baik, dan satu di mana kamu ingin menghitung kemiringan yang tepat.",explain:"Mengenali kapan presisi benar-benar penting versus kapan pembacaan visual kasar sudah cukup mencerminkan penilaian matematis yang matang.",hint:"Akankah perbandingan visual kasar berisiko saat membandingkan suku bunga tepat, tetapi baik-baik saja untuk sekilas santai 'mana yang naik lebih cepat'?",sample:"Untuk hal seperti sekilas melihat grafik untuk melihat mana dari dua tren yang naik lebih cepat, perbandingan visual cepat sudah baik-baik saja; tetapi untuk hal seperti menghitung suku bunga tepat dari grafik tabungan untuk membandingkan penawaran bank, menghitung kemiringan tepat dari dua titik data pasti jauh lebih penting."},
{n:74,type:"mcq",micro:"Menafsirkan nilai kemiringan nyata",q:"Sebuah grafik menunjukkan jarak vs waktu dengan kemiringan 60. Apa yang sebenarnya diwakili kemiringan ini dalam konteks ini?",options:["Jarak total 60 satuan yang sudah ditempuh sejak awal waktu","Waktu tempuh 60 satuan sebelum objek itu berhenti total","Kecepatan 60 satuan jarak per satuan waktu (seperti 60 km per jam)"],answer:2,explain:"Pada grafik jarak-vs-waktu, kemiringan mewakili kecepatan — laju perubahan jarak per satuan waktu.",hint:"Pada grafik jarak-vs-waktu, apakah kemiringan mewakili jumlah total, titik awal, atau laju?"},
{n:75,type:"open",micro:"Bekerja hati-hati di bawah tekanan",q:"Selama ujian berwaktu dengan beberapa sistem persamaan untuk diselesaikan, kebiasaan apa yang membantu menghindari kesalahan substitusi yang ceroboh?",explain:"Kebiasaan pemeriksaan-ganda yang spesifik dan cepat seperti ini membantu menjaga akurasi bahkan di bawah tekanan waktu.",hint:"Akankah memeriksa jawabanmu terhadap KEDUA persamaan asli menangkap kesalahan yang mungkin terlewat jika hanya memeriksa satu?",sample:"Selalu mengganti nilai yang ditemukan kembali ke KEDUA persamaan asli (bukan hanya satu) sebelum melanjutkan menangkap kesalahan substitusi atau hitung yang mungkin terlewat jika hanya menyelesaikan satu persamaan."},
{n:76,type:"mcq",micro:"Koneksi desain dunia nyata",q:"Mengapa sebuah aplikasi ride-share mungkin menunjukkan penumpang grafik perkiraan biaya vs jarak alih-alih hanya satu harga tunggal?",options:["Karena biayanya benar-benar berubah dengan laju tetap seiring jarak, jadi grafik (atau persamaan linear yang mendasarinya) membantu penumpang memperkirakan biaya untuk panjang perjalanan spesifik mereka sebelum memesan","Karena biaya sebenarnya berubah secara acak tanpa pola yang tetap seiring jarak, sehingga grafik hanya dipakai untuk hiasan tampilan aplikasi dan tidak membantu penumpang memperkirakan biaya","Karena penumpang tidak bisa memahami harga tunggal, dan grafik dipakai supaya perusahaan bebas mengubah tarif tanpa memberi tahu penumpang sebelum mereka memesan perjalanan"],answer:0,explain:"Grafik mengomunikasikan biaya yang benar-benar bervariasi dan berbasis-laju lebih berguna daripada satu angka tetap.",hint:"Akankah harga tetap tunggal secara akurat menggambarkan biaya yang sebenarnya berubah dengan jarak yang ditempuh?"},
{n:77,type:"open",micro:"Menjelaskan ke orang lain",q:"Seorang teman sekelas tidak mengerti mengapa kemiringan pada y=2x+3 adalah 2, bukan 3. Apa yang akan kamu jelaskan, dan mengapa itu membantu?",explain:"Menambatkan struktur abstrak y=mx+b ke posisi setiap angka mencerminkan pemahaman nyata di luar hafalan.",hint:"Dalam y=mx+b, apakah kemiringan itu angka yang mengalikan x, atau angka yang berdiri sendiri?",sample:"Saya akan menunjukkan bahwa dalam bentuk y=mx+b, m (angka yang mengalikan x) selalu kemiringan, sementara b (angka yang ditambahkan sendiri) adalah intersep-y — menghubungkan POSISI setiap angka dalam persamaan dengan artinya yang spesifik membantu menghindari mencampuradukkannya."},
{n:78,type:"mcq",micro:"Mengenali hasil sistem yang tidak konsisten",q:"Kamu menyelesaikan sebuah sistem dan kedua persamaan menyederhanakan menjadi garis yang persis sama, seperti y=2x+1 dan 2y=4x+2. Apa arti ini?",options:["Kedua persamaan mewakili garis yang berbeda tetapi sejajar, jadi tidak ada penyelesaian karena kedua garis tidak pernah bertemu","Kedua persamaan mewakili garis yang SAMA, jadi ada tak terhingga banyak penyelesaian (setiap titik pada garis itu memenuhi keduanya)","Kedua persamaan mewakili garis yang berpotongan di tepat satu titik, sehingga hanya ada satu pasangan (x, y) yang memenuhi keduanya"],answer:1,explain:"Ketika kedua persamaan menggambarkan garis yang identik, setiap titik di atasnya adalah penyelesaian bersama.",hint:"Jika kamu menyederhanakan 2y=4x+2, apakah itu berubah menjadi persamaan yang persis sama dengan y=2x+1?"},
{n:79,type:"open",micro:"Merancang sistem yang adil",q:"Rancang cara sederhana bagi kelas untuk menghindari kesalahan umum saat menyelesaikan sistem persamaan dengan substitusi.",explain:"Kebiasaan periksa-kedua-persamaan yang eksplisit adalah cara yang benar-benar praktis untuk menangkap kesalahan umum ini.",hint:"Akankah memeriksa jawaban yang ditemukan terhadap KEDUA persamaan asli membantu menangkap kesalahan tanda substitusi?",sample:"Mewajibkan siswa mengganti nilai-x yang ditemukan ke KEDUA persamaan asli untuk menyelesaikan y dan mengonfirmasi keduanya memberikan hasil yang sama, dan memeriksa ulang tandanya saat mengganti seluruh ekspresi (seperti 'x+3') ke persamaan lain, bukan hanya satu angka."},
{n:80,type:"mcq",micro:"Pemeriksaan keyakinan di berbagai percobaan berulang",q:"Kamu menyelesaikan sistem yang sama tiga kali dan mendapat (3,5) dua kali dan (5,3) sekali. Apa langkah berikutnya yang paling masuk akal?",options:["Pilih (3,5) saja karena muncul dua kali, tanpa perlu memeriksa lagi ke persamaan asli karena hasil mayoritas pasti benar dalam sistem persamaan apa pun","Pilih (5,3) saja karena muncul paling akhir, sehingga dianggap hasil perhitungan paling lengkap dan paling dapat dipercaya tanpa perlu diperiksa kembali","Ganti kedua jawaban kandidat ke KEDUA persamaan asli untuk melihat mana yang sebenarnya memenuhi keduanya — jangan hanya percaya hasil mayoritas begitu saja"],answer:2,explain:"Memverifikasi terhadap persamaan asli lebih andal daripada sekadar mempercayai jawaban mana pun yang paling sering muncul.",hint:"Apakah sebuah jawaban yang muncul lebih sering MENJAMIN itu benar, atau memeriksanya terhadap persamaan lebih andal?"},
{n:81,type:"open",micro:"Masalah nyata multi-langkah",q:"Dua paket gym: Paket A berbiaya Rp200.000/bulan tanpa biaya pendaftaran. Paket B berbiaya Rp500.000 pendaftaran plus Rp100.000/bulan. Susun dan selesaikan sistem untuk menemukan setelah berapa bulan kedua paket berbiaya total yang sama.",explain:"Menerjemahkan struktur biaya nyata setiap paket menjadi persamaan, lalu menyelesaikan sistemnya, menemukan bulan impas.",hint:"Apa dua bagian dari total biaya setiap paket, dan bagaimana mereka dibandingkan seiring waktu?",sample:"Misalkan m = bulan. Biaya Paket A: 200.000m. Biaya Paket B: 500.000+100.000m. Tetapkan sama: 200.000m=500.000+100.000m → 100.000m=500.000 → m=5 bulan, saat itu kedua paket berbiaya total Rp1.000.000."},
{n:82,type:"open",micro:"Merancang metode pemeriksaan nyata",q:"Kamu ingin memeriksa penyelesaian sistem-persamaan temanmu tanpa mengulang seluruh metodenya. Jelaskan pemeriksaan cepat.",explain:"Substitusi ke kedua persamaan asli adalah pemeriksaan yang cepat dan andal yang tidak bergantung pada metode penyelesai itu sendiri.",hint:"Akankah memasukkan jawaban (x,y) mereka ke KEDUA persamaan asli mengonfirmasi kebenarannya tanpa mengulang seluruh metode mereka?",sample:"Ganti jawaban (x,y) mereka ke KEDUA persamaan asli — jika keduanya terbukti benar, jawaban mereka benar, tanpa perlu mengulang langkah substitusi/eliminasi mereka."},
{n:83,type:"open",micro:"Menyelidiki klaim yang tidak konsisten",q:"Sebuah buku teks berkata sistem y=x+4 dan y=x+4 (persamaan yang persis sama dua kali) memiliki 'tak terhingga banyak penyelesaian.' Seorang siswa bersikeras sistem harus selalu memiliki tepat satu jawaban. Bagaimana kamu akan menyelidiki?",explain:"Menguji beberapa nilai secara langsung mengungkapkan apakah kumpulan penyelesaian suatu sistem adalah satu titik, tidak ada titik, atau setiap titik pada garis.",hint:"Jika kamu mencoba beberapa nilai x yang sangat berbeda, akankah kedua persamaan identik itu pernah tidak sepakat?",sample:"Menguji beberapa nilai x berbeda menunjukkan kedua persamaan selalu memberikan y yang sama untuk x apa pun, karena secara harfiah identik — artinya setiap titik pada garis itu memenuhi 'kedua' persamaan, mengonfirmasi tak terhingga banyak penyelesaian adalah kasus yang nyata dan valid."},
{n:84,type:"open",micro:"Koneksi sejarah/budaya",q:"Cari tahu (atau ingat kembali) bagaimana gagasan menggambar grafik persamaan pada kisi koordinat (sumbu x,y) muncul secara historis.",explain:"Menghubungkan teknik menggambar grafik saat ini dengan asal-usul sejarahnya yang genuine menunjukkan akar skill ini yang lebih dalam.",hint:"Pernahkah kamu mendengar koordinat disebut 'Kartesius' — dari nama siapa itu mungkin berasal?",sample:"Bidang koordinat sering dikreditkan kepada matematikawan abad ke-17 René Descartes, yang menghubungkan aljabar dan geometri dengan menunjukkan bahwa persamaan bisa diwakili sebagai bentuk/garis pada kisi — inilah mengapa koordinat kadang disebut 'koordinat Kartesius,' dan itu adalah dasar untuk menggambar grafik persamaan linear saat ini."},
{n:85,type:"open",micro:"Masalah nyata multi-langkah",q:"Sebuah lilin tingginya 15 cm dan terbakar habis 0,5 cm setiap jam. Tulis persamaan linear untuk tingginya h setelah t jam, lalu temukan berapa jam sampai tingginya 5 cm.",explain:"Menerjemahkan laju pembakaran nyata menjadi persamaan linear, lalu menyelesaikannya, menemukan waktu untuk mencapai tinggi target.",hint:"Berapa tinggi awalnya, dan seberapa banyak tinggi itu berkurang per jam?",sample:"h = 15 − 0,5t. Menetapkan h=5: 5=15−0,5t → 0,5t=10 → t=20 jam."},
{n:86,type:"open",micro:"Refleksi kesalahan",q:"Ceritakan saat nyata kamu membuat kesalahan dengan kemiringan, intersep, atau sistem persamaan — seperti kesalahan tanda, atau lupa memeriksa kedua persamaan. Apa yang akan kamu lakukan berbeda sekarang?",explain:"Merenungkan kesalahan pribadi yang nyata, dengan perbaikan konkret, menunjukkan skill ini sudah benar-benar tertanam.",hint:"Ingat kembali momen ketika jawaban kemiringan, intersep, atau sistem ternyata salah — apa tepatnya yang salah?",sample:"Bersifat personal dan terbuka — tujuannya adalah mengenali penyebab nyata dan menyebutkan perbaikan konkret, seperti memeriksa ulang tanda negatif yang didistribusikan atau selalu memverifikasi penyelesaian sistem di kedua persamaan."},
{n:87,type:"open",micro:"Merancang proyek kelas",q:"Rancang proyek kelas sederhana bagi 30 siswa untuk mempraktikkan menulis dan membandingkan persamaan linear dari situasi nyata (seperti paket telepon atau rekening tabungan).",explain:"Proyek praktis dan langsung yang menghubungkan penulisan persamaan, menggambar grafik, dan keputusan perbandingan nyata.",hint:"Akankah membuat kelompok menemukan dan mempresentasikan titik perpotongan sebenarnya membantu membuat perbandingan itu konkret dan berguna?",sample:"Minta kelompok kecil meneliti atau membuat 2 'paket' nyata (seperti dua paket telepon) dengan biaya tetap dan laju berbeda, tulis masing-masing sebagai persamaan linear, gambar grafik keduanya, temukan di mana mereka berpotongan, dan presentasikan paket mana yang lebih baik untuk tingkat penggunaan berbeda."},
{n:88,type:"open",micro:"Memperkirakan dan memverifikasi",q:"Perkirakan titik perpotongan y=x+1 dan y=3x-5 dengan mental math kasar, lalu verifikasi secara tepat.",explain:"Menerapkan teknik 'perkirakan dulu, lalu verifikasi secara tepat' pada sistem persamaan yang nyata.",hint:"Bisakah mental math kasar memberikan jawaban perkiraan yang masuk akal sebelum menyelesaikan secara tepat?",sample:"Perkiraan kasar: menetapkan x+1≈3x−5 berarti 6≈2x, jadi x≈3, y≈4; verifikasi tepat: x+1=3x−5 → 6=2x → x=3, y=4 — mengonfirmasi perkiraan itu."},
{n:89,type:"open",micro:"Menyelidiki perbedaan nyata",q:"Kamu dan temanmu menyelesaikan sistem yang sama, tetapi kalkulator grafik temanmu menunjukkan garis berpotongan di titik yang sedikit berbeda dari jawaban tanganmu. Berikan dua penjelasan dan cara memeriksa masing-masing.",explain:"Mempertimbangkan beberapa penyebab yang mungkin, dan cara mengujinya, mencerminkan penalaran investigatif yang genuine.",hint:"Bisakah perbedaan itu berasal dari kesalahan pengetikan, atau sekadar dari tampilan grafik yang membulatkan titik perpotongan?",sample:"Kemungkinan 1: kesalahan pengetikan saat memasukkan salah satu persamaan ke kalkulator — periksa ulang persamaan tepat yang dimasukkan. Kemungkinan 2: tampilan grafik kalkulator adalah perkiraan visual dan mungkin membulatkan titik perpotongan sedikit — selesaikan secara aljabar dengan tangan (substitusi) untuk jawaban tepat dan bandingkan."},
{n:90,type:"open",micro:"Koneksi statistik/rata-rata",q:"Sebuah laporan berkata 'rata-rata kemiringan pertumbuhan harga rumah di sebuah kota adalah Rp5.000.000/tahun.' Mengapa satu rata-rata tunggal ini mungkin tidak menggambarkan setiap lingkungan di kota itu?",explain:"Menghubungkan pemahaman kemiringan langsung dengan menafsirkan batasan nyata suatu statistik ringkasan dengan benar.",hint:"Apakah mengetahui HANYA rata-rata kemiringan seluruh kota memberitahumu bagaimana tren lingkungan tertentu mana pun sebenarnya?",sample:"Rata-rata menggabungkan laju pertumbuhan individual banyak lingkungan berbeda menjadi satu angka — beberapa lingkungan mungkin tumbuh jauh lebih cepat dan yang lain jauh lebih lambat atau bahkan menurun, jadi rata-rata seluruh kota tidak mencerminkan tren sebenarnya lingkungan tertentu mana pun."},
{n:91,type:"open",micro:"Mini proyek",q:"Rancang dan selesaikan skenario persamaan-linear nyata (seperti perbandingan biaya, tangki yang terkuras/terisi, atau target tabungan), menunjukkan persamaanmu, penyelesaianmu, dan metodemu.",explain:"Penerapan kapstone langsung dari keterampilan persamaan linear pada tugas nyata yang kamu rancang sendiri.",hint:"Akankah menunjukkan persamaanmu dan setiap langkah penyelesaian dengan jelas membuat pekerjaanmu lebih mudah diperiksa orang lain?",sample:"Bersifat personal dan terbuka — tujuannya adalah mempraktikkan penyusunan dan penyelesaian persamaan nyata dalam skenario realistis yang kamu rancang sendiri."},
{n:92,type:"open",micro:"Menjelaskan ke anak yang jauh lebih muda",q:"Bagaimana kamu akan menjelaskan arti 'kemiringan' kepada anak yang belum pernah melihat grafik sebelumnya?",explain:"Menambatkan konsep menggambar grafik abstrak ke pengalaman fisik yang konkret dan familier menunjukkan pemahaman yang mendalam dan bisa dipindahkan.",hint:"Bisakah membandingkan kemiringan dengan seberapa curam bukit atau tanjakan nyata terasa membuatnya lebih mudah dipahami?",sample:"Saya akan membandingkannya dengan seberapa curam bukit atau tanjakan terasa saat kamu berjalan menaikinya — kemiringan hanyalah angka yang memberitahumu seberapa banyak garis 'naik' untuk setiap langkah yang kamu ambil ke samping, persis seperti bukit yang lebih curam membuatmu mendaki lebih banyak untuk jarak maju yang sama."},
{n:93,type:"open",micro:"Refleksi tentang perjalanan Konkret-Piktorial-Abstrak",q:"Menurutmu mengapa memulai dengan pengalaman fisik nyata (seperti membandingkan kecuraman tanjakan atau perjalanan berkecepatan tetap) penting sebelum melanjutkan ke rumus kemiringan dan sistem persamaan abstrak?",explain:"Mencerminkan wawasan nyata tentang mengapa perjalanan Konkret-Piktorial-Abstrak sangat penting khususnya untuk persamaan linear.",hint:"Akankah rumus kemiringan lebih masuk akal bagi seseorang yang telah secara fisik mengalami laju yang stabil, atau bagi seseorang yang hanya menghafal rumusnya?",sample:"Tanpa dulu merasakan seperti apa laju perubahan tetap itu sebenarnya (kecepatan yang stabil, tangki yang terkuras secara stabil), rumus kemiringan abstrak bisa terasa seperti perhitungan tanpa makna alih-alih sesuatu yang menggambarkan pola perubahan yang nyata dan stabil — membangun dari pengalaman nyata dulu membantu rumus-rumus itu masuk akal secara konseptual nanti."},
{n:94,type:"open",micro:"Keputusan bisnis menggunakan persamaan linear",q:"Sebuah bisnis kecil menemukan bahwa menggambar grafik garis biaya dan pendapatannya untuk menemukan titik impas (di mana mereka berpotongan) membantu menentukan harga, tetapi membutuhkan pengumpulan data biaya yang akurat dulu. Keputusan bisnis apa yang mungkin didukung ini, dan apa yang harus mereka waspadai?",explain:"Menerapkan penalaran persamaan-linear pada trade-off bisnis nyata antara usaha analisis di awal dan keyakinan penetapan harga.",hint:"Akankah titik impas yang dihitung dari perkiraan biaya yang tidak akurat tetap bisa dipercaya?",sample:"Mereka mungkin memutuskan analisis itu sepadan dengan usaha penyusunannya sebelum meluncurkan produk baru, untuk mengetahui berapa unit yang harus mereka jual untuk mendapat keuntungan — tetapi harus waspada apakah perkiraan biaya dan pendapatan mereka yang masuk ke dalam persamaan itu realistis, karena perkiraan yang salah akan membuat titik impas itu menyesatkan."},
{n:95,type:"open",micro:"Persamaan linear bertemu keadilan",q:"Tiga teman menginvestasikan jumlah berbeda ke bisnis bersama (Rp1.000.000, Rp2.000.000, Rp3.000.000) dan ingin membagi keuntungan Rp12.000.000 secara proporsional terhadap investasi mereka menggunakan persamaan. Jelaskan bagaimana mereka akan menyusun ini.",explain:"Menghubungkan penyelesaian persamaan langsung dengan diskusi keadilan nyata tentang membagi keuntungan bersama secara proporsional.",hint:"Akankah membagi keuntungan menjadi tiga bagian yang persis sama secara adil mencerminkan fakta bahwa mereka menginvestasikan jumlah yang berbeda?",sample:"Misalkan x = keuntungan per Rp1.000.000 yang diinvestasikan. Maka 1.000.000x+2.000.000x+3.000.000x=12.000.000 → 6.000.000x=12.000.000 → x=2, jadi para teman mendapat Rp2.000.000, Rp4.000.000, dan Rp6.000.000 masing-masing — persamaan itu menjamin pembagian cocok dengan investasi sebenarnya setiap orang alih-alih pembagian tiga arah yang sama."},
{n:96,type:"open",micro:"Batasan sebuah statistik",q:"Sebuah laporan menyatakan 'laju rata-rata pertumbuhan pendapatan perusahaan adalah kemiringan Rp10.000.000/bulan.' Apa yang bisa diberitahukan angka ini, dan apa yang tidak bisa?",explain:"Mengenali bahwa statistik kemiringan memberikan angka umum yang berguna, tetapi bukan gambaran bulan-per-bulan penuh, adalah koneksi berpikir kritis yang penting.",hint:"Bisakah sebuah perusahaan memiliki hasil yang sangat berbeda dari bulan ke bulan, tetapi tetap rata-ratanya sama dengan kemiringan keseluruhan yang sama?",sample:"Ini bisa memberitahumu tren pertumbuhan khas umum — tetapi tidak bisa memberitahumu sendiri apakah pertumbuhan itu stabil setiap bulan atau sangat tidak merata (seperti pertumbuhan besar beberapa bulan dan kerugian bulan lain) yang kebetulan rata-ratanya menjadi kemiringan keseluruhan yang sama itu."},
{n:97,type:"open",micro:"Investigasi nyata multi-langkah",q:"Rancang rencana untuk mengetahui, menggunakan persamaan linear, paket harga ride-share mana dari dua yang lebih murah untuk penggunaan bulananmu yang khas, tanpa kalkulator finansial.",explain:"Menerapkan strategi 'susun persamaan, temukan titik perpotongan, bandingkan dengan penggunaan nyata' pada keputusan yang benar-benar praktis.",hint:"Akankah mengetahui titik perpotongan tepat antara kedua paket membantumu memutuskan berdasarkan penggunaan KHASMU?",sample:"Tulis biaya setiap paket sebagai persamaan linear dalam bentuk jumlah perjalanan, hitung/gambar grafik keduanya untuk beberapa jumlah perjalanan yang realistis, temukan di mana mereka berpotongan, dan bandingkan paket mana yang lebih murah di bawah versus di atas titik perpotongan itu relatif terhadap jumlah perjalanan bulananmu yang khas."},
{n:98,type:"open",micro:"Persamaan linear dan teknologi",q:"Kalkulator dan aplikasi grafik bisa langsung menggambar garis dan menemukan titik perpotongan. Apa satu keuntungan dan satu risiko dari sepenuhnya mempercayai ini tanpa memahami aljabar yang mendasarinya?",explain:"Memperluas penalaran persamaan-linear ke alat digital nyata, menimbang kenyamanan melawan risiko kesalahan input yang tidak terdeteksi.",hint:"Jika kamu memasukkan persamaan dengan kemiringan dan intersep tertukar, akankah sebuah aplikasi memperingatkanmu, atau hanya menggambar garis yang salah tetapi terlihat percaya diri?",sample:"Keuntungan: langsung memvisualisasikan dan menemukan perpotongan tepat untuk sistem kompleks menghemat waktu yang signifikan. Risiko: jika kamu tidak memahami bentuk kemiringan-intersep, kamu mungkin memasukkan persamaan dengan salah (seperti menukar kemiringan dan intersep) tanpa menyadari grafik yang dihasilkan terlihat salah."},
{n:99,type:"open",micro:"Menyelidiki angka yang bertentangan",q:"Dua sumber berbeda memberikan kemiringan pertumbuhan sebuah perusahaan sebagai Rp9.800.000/bulan dan Rp10.200.000/bulan. Bagaimana seharusnya pembaca yang cermat memikirkan ini?",explain:"Menerapkan penalaran investigatif yang adil pada skenario angka-yang-bertentangan yang nyata, menghindari asumsi bahwa salah satu sumber sekadar salah.",hint:"Bisakah dua sumber benar-benar menghitung kemiringan yang sedikit berbeda dari rentang tanggal berbeda dari data dasar yang sama?",sample:"Pembaca yang cermat sebaiknya mempertimbangkan bahwa kedua angka itu mungkin berasal dari periode waktu atau metode pengukuran yang sedikit berbeda (misalnya, tanggal mulai/akhir yang berbeda untuk data yang digunakan menghitung kemiringan) alih-alih mengasumsikan satu sumber membuat kesalahan langsung, dan sebaiknya memeriksa rentang data yang mendasari setiap sumber sebelum memutuskan mana yang lebih cocok untuk tujuan mereka."},
{n:100,type:"open",micro:"Refleksi kapstone",q:"Melihat kembali skill Persamaan Linear ini — mulai dari tanjakan nyata dan kecepatan tetap, ke garis grafik dan tabel, dan akhirnya ke rumus kemiringan abstrak dan sistem persamaan — kebiasaan apa yang sekarang kamu miliki saat melihat persamaan linear atau grafik?",explain:"Menyebutkan kebiasaan baru yang konkret, terkait perjalanan konkret-ke-abstrak dari skill ini, adalah tanda paling jelas bahwa skill ini sudah tertanam.",hint:"Pikirkan momen dalam unit ini ketika kemiringan dan titik perpotongan berhenti membutuhkan gambar dan mulai masuk akal sebagai gagasan abstrak dengan sendirinya.",sample:"Bersifat personal dan terbuka — carilah perubahan nyata, seperti secara otomatis menghubungkan angka kemiringan dengan laju perubahan nyata, memeriksa penyelesaian sistem di kedua persamaan asli, atau mengenali apa yang sebenarnya diwakili titik perpotongan grafik sebelum menghitung."},
];
